from schema import final

final(11,1,'رمزکردن شدت محرک','true_false','شدت محرک پایدارِ مؤثر بر یک گیرندهٔ حسی را در مدت برابر و محدودهٔ غیرآسیب‌زا بیشتر می‌کنیم. درستی عبارت را تعیین و اصلاح کنید و روش معمول رمزکردن شدت را بنویسید: «در نورون حسی، ارتفاع هر پتانسیل عمل به نسبت شدت محرک بیشتر می‌شود.»','نادرست است. پتانسیل عمل از قانون همه یا هیچ پیروی می‌کند و دامنهٔ آن در شرایط یکسان تقریباً ثابت است. افزایش شدت محرک پایدار می‌تواند با افزایش بسامد پیام‌های نورون حسی در محدودهٔ توان آن رمز شود.', [('نادرست‌بودن و ثابت‌بودن نسبی دامنه',0.5),('نقش بسامد در رمزکردن شدت',0.5)],truth=False)
final(11,1,'پتانسیل عمل','diagram_label','در نمودار پتانسیل عمل، P بخش صعودی و R بخش نزولی است. در هر بخش، جهت حرکت عمدهٔ یون مؤثر را بنویسید و تفاوت آن را با نقش پمپ سدیم‌ـ‌پتاسیم بیان کنید.','در P، ورود سدیم از دریچه‌های وابسته به ولتاژ در مثبت‌ترشدن درون نقش عمده دارد. در R، خروج پتاسیم به منفی‌ترشدن مجدد کمک می‌کند. پمپ سدیم‌ـ‌پتاسیم با مصرف ATP در حفظ اختلاف غلظت یون‌ها نقش دارد و با باز و بسته‌شدن سریع این دریچه‌ها یکی نیست.', [('ورود سدیم در P',0.5),('خروج پتاسیم در R',0.5),('تمایز نقش پمپ در حفظ شیب‌ها با دریچه‌ها و مصرف ATP',0.5)],image='diagrams/neuron.png',imageDescription='منحنی تغییر پتانسیل غشا برحسب زمان؛ P روی بخش بالارونده و R روی بخش پایین‌رونده است.')
final(11,1,'انعکاس','short','آیا شروع دورکردن دست از جسم داغ پیش از آگاهی کامل از درد، به معنی دخالت‌نداشتن دستگاه عصبی مرکزی است؟ دلیل بیاورید.','خیر. نخاع بخشی از دستگاه عصبی مرکزی است و مدار انعکاسی می‌تواند پاسخ حرکتی را در آن آغاز کند. هم‌زمان پیام حسی به مغز نیز می‌رسد و ادراک درد رخ می‌دهد.', [('نخاع به‌عنوان بخشی از دستگاه مرکزی',0.5),('شروع پاسخ نخاعی همراه امکان رسیدن پیام به مغز',0.5)])

final(11,2,'تطابق چشم','fill_blank','در دید نزدیک، ماهیچهٔ مژگانی .......... می‌شود، کشش تارهای آویزی .......... و انحنای عدسی .......... می‌یابد.','منقبض؛ کاهش می‌یابد؛ افزایش.', [('انقباض ماهیچهٔ مژگانی',0.5),('کاهش کشش تارهای آویزی',0.5),('افزایش انحنای عدسی',0.5)])
final(11,2,'بینایی','definition_comparison','گیرنده‌های استوانه‌ای و مخروطی شبکیه را از نظر کارایی در نور کم و نقش در دید رنگی مقایسه کنید.','استوانه‌ای‌ها در نور کم حساس‌ترند و در دید کم‌نور نقش مهم دارند، اما تشخیص رنگ را به شکل مخروطی‌ها انجام نمی‌دهند. مخروطی‌ها برای عملکرد مناسب نور بیشتری می‌خواهند و در دید رنگی و جزئیات نقش دارند.', [('حساسیت بیشتر استوانه‌ای‌ها در نور کم',0.5),('نقش مخروطی‌ها در دید رنگی و نیاز به نور بیشتر',0.5)])
final(11,2,'گوش و تعادل','matching','ساختار را به نقش مناسب وصل کنید: الف) حلزون، ب) مجاری نیم‌دایره‌ای، پ) استخوانچه‌های گوش میانی. نقش‌ها: ۱) انتقال و تقویت ارتعاش، ۲) دریافت تغییر حرکت چرخشی سر، ۳) دخالت در دریافت پیام شنوایی.','الف–۳؛ ب–۲؛ پ–۱.', [('حلزون و شنوایی',0.5),('مجاری و حرکت چرخشی',0.5),('استخوانچه‌ها و انتقال/تقویت ارتعاش',0.5)],promptParts=[{'id':'a','text':'حلزون'},{'id':'b','text':'مجاری نیم‌دایره‌ای'},{'id':'c','text':'استخوانچه‌ها'}])

final(11,3,'لغزش رشته‌ها','true_false','درستی عبارت را تعیین و اصلاح کنید: «کوتاه‌شدن سارکومر هنگام انقباض معمول، نتیجهٔ کوتاه‌شدن طول تک‌تک رشته‌های اکتین و میوزین است.»','نادرست است. طول خود رشته‌ها در انقباض معمول تغییر عمده‌ای نمی‌کند؛ با لغزش و افزایش هم‌پوشانی آن‌ها، خطوط Z به هم نزدیک و سارکومر کوتاه می‌شود.', [('تشخیص نادرست‌بودن',0.5),('ثابت‌بودن طول رشته‌ها و افزایش هم‌پوشانی',0.5),('نزدیک‌شدن خطوط Z',0.5)],truth=False)
final(11,3,'ماهیچه‌های مخالف','short','چرا برای خم‌کردن و بازکردن ساعد از ماهیچه‌های مخالف استفاده می‌شود؟ پاسخ را به نوع نیروی انقباض مربوط کنید.','ماهیچهٔ اسکلتی در انقباض نیروی کششی ایجاد می‌کند و استخوان را فعالانه در جهت مخالف هل نمی‌دهد. انقباض هماهنگ ماهیچهٔ مخالف می‌تواند حرکت بازگشت را در جهت مقابل ایجاد کند.', [('کششی‌بودن نیروی انقباض',0.5),('لزوم کشش ماهیچهٔ مخالف برای جهت مقابل',0.5)])
final(11,3,'ساختار استخوان','essay','در آزمایشی، مواد معدنی یک قطعهٔ استخوان کاهش می‌یابد ولی رشته‌های آلی باقی می‌مانند. پیش‌بینی کنید سختی و انعطاف‌پذیری نسبی آن چه تغییری می‌کند و هر تغییر را به یک جزء ساختاری مربوط کنید.','با کاهش مواد معدنی، سختی و مقاومت فشاری کاهش می‌یابد و قطعه نسبت به استخوان طبیعی انعطاف‌پذیرتر می‌شود. رشته‌های آلی، از جمله کلاژن، هنوز در مقاومت کششی و انعطاف‌پذیری نقش دارند. استخوان طبیعی از همکاری این دو بخش استحکام مناسب می‌گیرد.', [('کاهش سختی/مقاومت فشاری با کاهش مواد معدنی',0.5),('باقی‌بودن نقش بخش آلی در انعطاف و کشش',0.5),('ارتباط ترکیب دو جزء با ویژگی استخوان طبیعی',0.5)])

final(11,4,'یاختهٔ هدف','definition_comparison','فرق «رسیدن هورمون با خون به یک یاخته» و «هدف‌بودن آن یاخته» چیست؟ نقش گیرنده را توضیح دهید.','هورمون درون‌ریز ممکن است با خون در معرض یاخته‌های زیادی قرار بگیرد. یاختهٔ هدف گیرندهٔ مناسب و توان پاسخ به آن هورمون را دارد؛ بنابراین تماس یا حضور هورمون به‌تنهایی پاسخ اختصاصی را تضمین نمی‌کند.', [('توزیع خونی به یاخته‌های متعدد',0.5),('گیرندهٔ مناسب و پاسخ اختصاصی یاختهٔ هدف',0.5)])
final(11,4,'قند خون','matching','هورمون‌ها را به اثر معمول مناسب وصل کنید: الف) انسولین، ب) گلوکاگون، پ) محرک تیروئید. اثرها: ۱) تحریک فعالیت تیروئید، ۲) کمک به کاهش قند خون، ۳) کمک به افزایش قند خون.','الف–۲؛ ب–۳؛ پ–۱. اثرها به یاخته‌های هدف و شرایط تنظیمی وابسته‌اند.', [('انسولین و کاهش قند',0.5),('گلوکاگون و افزایش قند',0.5),('محرک تیروئید و تحریک غده',0.5)],promptParts=[{'id':'a','text':'انسولین'},{'id':'b','text':'گلوکاگون'},{'id':'c','text':'محرک تیروئید'}])
final(11,4,'بازخورد منفی','essay','وقتی هورمون‌های تیروئیدی خون از حد مناسب بیشتر شوند، بازخورد منفی چگونه می‌تواند از افزایش بیشتر آن‌ها جلوگیری کند؟ مسیر را در حد کتاب توضیح دهید.','افزایش هورمون‌های تیروئیدی بر مراکز تنظیمی بالادست اثر مهاری می‌گذارد و ترشح محرک تیروئید از هیپوفیز کاهش می‌یابد. تحریک کمتر تیروئید، تولید و ترشح بیشتر هورمون را محدود می‌کند. جهت پاسخ با تغییر اولیه مخالفت می‌کند.', [('کاهش تحریک بالادست/محرک تیروئید',0.5),('کاهش تحریک تیروئید و محدودشدن ترشح',0.5),('توضیح مخالفت پاسخ با افزایش اولیه',0.5)])

final(11,5,'خاطرهٔ ایمنی','true_false','درستی عبارت را تعیین و اصلاح کنید: «دریافت پادتن آماده الزاماً همان خاطرهٔ ایمنی پایدارِ حاصل از پاسخ فعال بدن را ایجاد می‌کند.»','نادرست است. دریافت پادتن آماده ایمنی غیرفعال می‌دهد و به‌خودی‌خود ایجاد یاختهٔ خاطره در گیرنده را تضمین نمی‌کند. در ایمنی فعال، پاسخ خود بدن می‌تواند با ایجاد یاخته‌های خاطره همراه شود.', [('تشخیص نادرست‌بودن',0.5),('تفاوت ایمنی غیرفعال با ایجاد خاطره در ایمنی فعال',0.5)],truth=False)
final(11,5,'دفاع اختصاصی','fill_blank','لنفوسیت B فعال می‌تواند به یاختهٔ .......... تبدیل شود و پروتئین دفاعی .......... ترشح کند؛ لنفوسیت T کشنده می‌تواند یاختهٔ .......... را هدف قرار دهد.','پادتن‌ساز/پلاسما؛ پادتن؛ آلوده (یا یاختهٔ هدف شناسایی‌شده، مانند یاختهٔ آلوده به ویروس).', [('یاختهٔ پادتن‌ساز/پلاسما',0.5),('پادتن',0.5),('یاختهٔ آلوده/هدف مناسب T کشنده',0.5)])
final(11,5,'التهاب','essay','پس از آسیب سطحی پوست، قرمزی و تورم ایجاد می‌شود. این دو نشانه را به تغییر رگ‌های موضع و دسترسی عوامل دفاعی مرتبط کنید؛ چرا این پاسخ به‌تنهایی نشانهٔ ایجاد خاطرهٔ اختصاصی نیست؟','گشادشدن رگ‌ها خون‌رسانی را بیشتر و قرمزی ایجاد می‌کند. افزایش نفوذپذیری، خروج مایع و دسترسی یاخته‌ها و عوامل دفاعی را تسهیل می‌کند و می‌تواند تورم بدهد. التهاب بخشی از دفاع غیراختصاصی است؛ ایجاد خاطره به فعال‌شدن و تمایز لنفوسیت‌های اختصاصی مربوط است و صرف التهاب آن را ثابت نمی‌کند.', [('افزایش خون‌رسانی و قرمزی',0.5),('نفوذپذیری/خروج مایع و تورم/دسترسی دفاعی',0.5),('تفکیک التهاب غیراختصاصی از خاطرهٔ اختصاصی',0.5)])

final(11,6,'دنا و فام‌تن','diagram_label','در نمودار مقدار نسبی دنا، A پیش از همانندسازی، B پس از آن و C برای یک دختر پس از میتوز است. توضیح دهید چرا مقدار B دو برابر A است ولی لزوماً تعداد فام‌تن‌های B دو برابر نشده است. بازگشت مقدار دنا در C به سطح A را نیز تفسیر کنید.','در همانندسازی، هر فام‌تن دارای دو کروماتید خواهری می‌شود و هر کروماتید یک مولکول دنا دارد؛ پس مقدار دنا دو برابر می‌شود. تا پیش از جدایی کروماتیدها، شمار سانترومرها و در نتیجه شمار فام‌تن‌ها همان است. بعد از تقسیم طبیعی، هر دختر مقدار دنا مشابه A دریافت می‌کند.', [('دو برابرشدن دنا با دوکروماتیدی‌شدن',0.5),('ثبات تعداد فام‌تن پیش از جدایی با معیار سانترومر',0.5),('تفسیر بازگشت مقدار هر دختر در C',0.5)],image='diagrams/cell_dna.png',imageDescription='نمودار مقدار نسبی دنا در سه وضعیت A=۲، B=۴ و C=۲.')
final(11,6,'دو تقسیم میوز','definition_comparison','آنچه در تقسیم نخست میوز جدا می‌شود با آنچه در تقسیم دوم جدا می‌شود مقایسه کنید و بگویید آیا بین این دو تقسیم همانندسازی دنا انجام می‌شود.','در تقسیم نخست، فام‌تن‌های همتا از هم جدا می‌شوند و تعداد مجموعه‌های فام‌تنی کاهش می‌یابد. در تقسیم دوم، کروماتیدهای خواهری جدا می‌شوند. میان دو تقسیم، همانندسازی دوبارهٔ دنا انجام نمی‌شود.', [('جدایی همتاها در میوز نخست',0.5),('جدایی خواهری در میوز دوم',0.5),('نبود همانندسازی بین دو تقسیم',0.5)])
final(11,6,'وارسی چرخهٔ یاخته','short','در بافتی، یک یاخته با دنای آسیب‌دیده بدون ترمیم وارد تقسیم می‌شود. توضیح دهید چرا عبور از مرحلهٔ وارسی بدون رفع آسیب می‌تواند برای یاخته‌های دختر و بافت زیان‌آور باشد.','آسیب دنا ممکن است به یاخته‌های دختر منتقل و کارکرد ژن‌ها یا تنظیم رشد را مختل کند. مرحله‌های وارسی با توقف چرخه در شرایط نامناسب فرصت ترمیم فراهم می‌کنند و از تداوم بی‌مهار خطاها می‌کاهند؛ هر آسیب الزاماً سرطان نمی‌سازد.', [('امکان انتقال آسیب و اختلال در کارکرد/تنظیم رشد',0.5),('نقش وارسی در توقف و فراهم‌کردن فرصت ترمیم',0.5)])

final(11,7,'چرخهٔ تولیدمثل','fill_blank','در چرخهٔ بدون بارداری، تحلیل .......... با افت پروژسترون همراه است و کاهش حمایت هورمونی از .......... رحم می‌تواند به ریزش آن بینجامد.','جسم زرد؛ درون‌شامه/آندومتر.', [('جسم زرد',0.5),('درون‌شامه/آندومتر',0.5)])
final(11,7,'لقاح و لانه‌گزینی','definition_comparison','لقاح و لانه‌گزینی طبیعی انسان را از نظر محل معمول و ترتیب زمانی مقایسه کنید.','لقاح، آمیزش گامت‌ها و تشکیل تخم، معمولاً در لولهٔ رحم رخ می‌دهد. جنین آغازین در مسیر تقسیم می‌شود و بعدتر در درون‌شامهٔ رحم لانه‌گزینی می‌کند. بنابراین این دو رویداد در زمان و محل یکسان نیستند.', [('لقاح در لولهٔ رحم و تشکیل تخم',0.5),('لانه‌گزینی بعدی در درون‌شامهٔ رحم',0.5),('تقسیمات آغازین در مسیر/ترتیب زمانی درست',0.5)])
final(11,7,'جفت','essay','توضیح دهید چگونه جفت می‌تواند اکسیژن را از مادر به جنین برساند، بی‌آنکه لازم باشد خون دو فرد در یک رگ مشترک کاملاً مخلوط شود. به اهمیت سطح تبادل اشاره کنید.','دو گردش در جفت در نزدیکی هم قرار می‌گیرند و یک سطح تبادل نازک با سطح تماس مناسب فراهم می‌شود. اکسیژن در جهت اختلاف فشار نسبی از سد تبادل می‌گذرد و وارد خون جنین می‌شود. عبور مولکول با مخلوط‌شدن مستقیم کل خون دو گردش یکسان نیست.', [('نزدیکی گردش‌ها و سطح تبادل مناسب',0.5),('عبور اکسیژن با اختلاف فشار نسبی',0.5),('تفکیک تبادل ماده از اختلاط مستقیم خون',0.5)])

final(11,8,'لقاح مضاعف','true_false','درستی عبارت را تعیین و اصلاح کنید: «در لقاح مضاعف معمول نهاندانگان، هر دو زامه با تخم‌زا آمیزش می‌یابند و دو جنین دولاد یکسان می‌سازند.»','نادرست است. یک زامه با تخم‌زا آمیزش می‌یابد و تخم دولاد را می‌سازد. زامهٔ دیگر با یاختهٔ مرکزی دارای دو هستهٔ قطبی آمیزش می‌یابد و فرآوردهٔ معمول سه‌لادِ سازندهٔ آندوسپرم پدید می‌آید.', [('تشخیص نادرست‌بودن',0.5),('زامه و تخم‌زا/تخم دولاد',0.5),('زامه و دو هستهٔ قطبی/فرآوردهٔ سه‌لاد',0.5)],truth=False)
final(11,8,'گرده‌افشانی','short','اگر گرده روی کلاله قرار بگیرد ولی لولهٔ گرده نتواند به کیسهٔ رویانی برسد، کدام مرحله انجام شده و کدام مرحله ممکن است انجام نشود؟ دلیل بنویسید.','گرده‌افشانی انجام شده است؛ اما لقاح ممکن است رخ ندهد، زیرا زامه‌ها برای رسیدن به کیسهٔ رویانی به رشد لولهٔ گرده نیاز دارند. صرف انتقال گرده تشکیل تخم را تضمین نمی‌کند.', [('تفکیک گرده‌افشانی انجام‌شده از لقاح',0.5),('نیاز به رساندن زامه با لولهٔ گرده',0.5)])
final(11,8,'سرنوشت بخش‌های گل','matching','منشأ را به فرآوردهٔ معمول مربوط وصل کنید: الف) تخم، ب) پوشش تخمک، پ) دیوارهٔ تخمدان. فرآورده‌ها: ۱) پوستهٔ دانه، ۲) جنین، ۳) دیوارهٔ میوه.','الف–۲؛ ب–۱؛ پ–۳.', [('تخم و جنین',0.5),('پوشش تخمک و پوستهٔ دانه',0.5),('دیوارهٔ تخمدان و دیوارهٔ میوه',0.5)],promptParts=[{'id':'a','text':'تخم'},{'id':'b','text':'پوشش تخمک'},{'id':'c','text':'دیوارهٔ تخمدان'}])

final(11,9,'نورگرایی','essay','ساقه‌ای جوان در نور یک‌طرفه به سوی نور خم می‌شود. ارتباط توزیع نامساوی اکسین، رشد دو سمت و جهت خم‌شدن را در یک توضیح پیوسته بیان کنید.','در ساقهٔ جوان، در پاسخ به نور یک‌طرفه، توزیع اکسین به نفع سمت سایه تغییر می‌کند. در محدودهٔ مناسب، اکسین رشد طولی یاخته‌های آن سمت را بیشتر می‌کند. سمت سایه بلندتر می‌شود و ساقه به طرف نور خم می‌شود؛ جهت خم‌شدن به سمت رشد کمتر است.', [('توزیع بیشتر اکسین در سمت سایه',0.5),('رشد طولی بیشتر سمت سایه در محدودهٔ مناسب',0.5),('ارتباط رشد نابرابر با خم‌شدن به نور',0.5)])
final(11,9,'هورمون‌های گیاهی','matching','پیام‌رسان را به اثر مرتبط وصل کنید: الف) اتیلن، ب) آبسیزیک‌اسید، پ) اکسینِ رأس ساقه. اثرها: ۱) نقش در چیرگی رأسی، ۲) کمک به رسیدن میوهٔ حساس، ۳) کمک به بسته‌شدن روزنه در کم‌آبی.','الف–۲؛ ب–۳؛ پ–۱.', [('اتیلن و رسیدن میوه',0.5),('آبسیزیک‌اسید و بسته‌شدن روزنه',0.5),('اکسین رأس و چیرگی رأسی',0.5)],promptParts=[{'id':'a','text':'اتیلن'},{'id':'b','text':'آبسیزیک‌اسید'},{'id':'c','text':'اکسین رأس'}])
final(11,9,'خواب بذر','short','بذری ذخیرهٔ غذایی فراوان دارد، اما در شرایط نامناسب محیطی در حالت خواب باقی می‌ماند. چرا وجود ذخیره به‌تنهایی جوانه‌زنی فوری را تضمین نمی‌کند؟ به نقش آبسیزیک‌اسید اشاره کنید.','جوانه‌زنی علاوه بر ذخیرهٔ غذایی به شرایط مناسب و تنظیم رشد وابسته است. آبسیزیک‌اسید می‌تواند جوانه‌زنی را مهار و به حفظ خواب بذر کمک کند؛ بنابراین وجود سوخت کافی، برطرف‌شدن مهار رشد را تضمین نمی‌کند.', [('تفکیک داشتن ذخیره از مناسب‌بودن شرایط و تنظیم رشد',0.5),('نقش مهاری آبسیزیک‌اسید در جوانه‌زنی/خواب',0.5)])
